<?php
declare(strict_types=1);
require_once __DIR__.'/fixtures/PrintifyApiApprovalFixture.php';
require_once __DIR__.'/fixtures/NativeApprovedPackageFixture.php';
require_once __DIR__.'/fixtures/Shop2BoundPackageFixture.php';
use DigiForge\Database\Tables;
final class Shop2BoundPackageExportTest extends WP_UnitTestCase {
 use NativeApprovedPackageFixture,Shop2BoundPackageFixture;
 private PrintifyApiApprovalFixture $fixture;private array $rows=[];
 protected function setUp():void{parent::setUp();$this->fixture=new PrintifyApiApprovalFixture();$this->fixture->boot();global $wpdb;foreach([Tables::opportunities(),Tables::product_families(),Tables::products(),Tables::product_versions(),Tables::production_plans(),Tables::pod_mappings(),Tables::pod_business_mappings(),Tables::asset_specs(),Tables::production_plan_assets()]as $t)$this->rows[$t]=$wpdb->get_results('SELECT * FROM '.$t,ARRAY_A);DigiForge\Core\Settings::protectProduction();}
 protected function tearDown():void{try{global $wpdb;$wpdb->query('ROLLBACK');foreach($this->rows as $t=>$rows){$wpdb->query('DELETE FROM '.$t);foreach($rows as $row)$wpdb->insert($t,$row,array_fill(0,count($row),'%s'));}$this->fixture->restore();}finally{parent::tearDown();}}
 public static function families():array{return [['mug'],['poster']];}
 /** @dataProvider families */
 public function testActualPortalExportRejectsNonexistentSelectedProof(string $family):void{
  $p=$this->approvedNativePackage($family,true);$v=PrintifyApiApprovalFixture::checked((new DigiForge\POD\ProductPackageRepository())->read('personalized_pod',$p['package']));$post=['operation'=>'package_export','shop_key'=>'personalized_pod','supplier_workflow_hash'=>$p['workflow'],'workflow_hash'=>$v['record']['commercial_design_metadata']['commercial_hash'],'factory_hash'=>$v['record']['commercial_design_metadata']['design_hash'],'package_hash'=>$p['package'],'personalization_hash'=>str_repeat('f',64),'confirm'=>'1'];
  self::assertWPError((new DigiForge\Portal\Shop2ProductWorkflowPanel())->process($post),'A nonexistent selected proof must not yield a Shop2 held export.');
 }
 /** @dataProvider families */
 public function testExactReviewedProofAndBusinessAreBoundAndEveryInvalidPathDenies(string $family):void{
  $http=0;$deny=static function()use(&$http){++$http;throw new RuntimeException('External HTTP forbidden');};add_filter('pre_http_request',$deny,PHP_INT_MAX);
  try{
   $f=$this->reviewedBoundPackage($family);$panel=new DigiForge\Portal\Shop2ProductWorkflowPanel();$post=$f['context']+['operation'=>'package_export','package_hash'=>$f['package'],'confirm'=>'1'];$ok=PrintifyApiApprovalFixture::checked($panel->process($post));$raw=$ok['package_export'];$out=json_decode($raw,true,32,JSON_THROW_ON_ERROR);$v=PrintifyApiApprovalFixture::checked((new DigiForge\POD\ProductPackageRepository())->read('personalized_pod',$f['package']));
   self::assertSame($v['record']['evidence']['shop2_binding'],$out['proof_business_binding']);$bound=$out['proof_business_binding'];self::assertSame($f['proof']['hash'],$bound['personalization_intake']['versions']['proof_hash']);self::assertSame($f['proof']['review']['hash'],$bound['personalization_intake']['versions']['review_hash']);self::assertSame($f['intake']['intake_hash'],$bound['personalization_intake']['intake_hash']);self::assertSame($f['product_version_id'],$bound['business']['product_version_id']);self::assertSame($f['mapping'],$bound['business']['selectors']['provider_mapping_id']);self::assertSame($f['package'],$out['immutable_package_record_sha256']);self::assertFalse($out['external_execution_authorized']);self::assertTrue($out['release_hold']);self::assertStringNotContainsString('<svg',$raw);self::assertStringNotContainsString('Élodie',$raw);
   // An unrelated draft does not silently become the selected proof or invalidate the old selected one.
   $proofs=new DigiForge\Research\ArtworkPersonalizationRepository();$next=PrintifyApiApprovalFixture::checked($proofs->sample('personalized_pod',$f['schema']['hash'],['name_a'=>'Sam','name_b'=>'Alex','anniversary_date'=>'2024-02-29'],$f['proof']['hash']));
   $replay=PrintifyApiApprovalFixture::checked($panel->process($post));self::assertSame($raw,$replay['package_export']);
   foreach([['personalization_hash',str_repeat('f',64)],['proof_hash',$next['hash']],['schema_hash',str_repeat('a',64)],['review_hash',str_repeat('a',64)],['intake_hash',str_repeat('a',64)],['business_mapping_id',(string)($f['mapping']+9999)],['shop_key','digital'],['business_mapping_id',null],['business_mapping_id',true],['proof',['approved'=>true]]]as [$key,$value])self::assertWPError($panel->process(array_replace($post,[$key=>$value])),$key);
   global $wpdb;$proofKey='digiforge_shop2_personalization_version_'.$f['proof']['hash'];$schemaKey='digiforge_shop2_personalization_version_'.$f['schema']['hash'];$reviewKey='digiforge_shop2_personalization_version_'.$f['proof']['review']['hash'];$pointer='digiforge_shop2_personalization_decision_'.$f['proof']['hash'];
   foreach([$proofKey,$schemaKey,$reviewKey,$pointer]as $key){$original=$wpdb->get_var($wpdb->prepare('SELECT option_value FROM '.$wpdb->options.' WHERE option_name=%s',$key));self::assertIsString($original);try{$wpdb->update($wpdb->options,['option_value'=>'{}'],['option_name'=>$key],['%s'],['%s']);self::assertWPError($panel->process($post),$key);self::assertWPError((new DigiForge\POD\ProductPackageRepository())->export('personalized_pod',$f['package']),'Ordinary repository export cannot bypass the bound-proof denial.');self::assertWPError((new DigiForge\Portal\ProductPackagePanel())->process($post),'Ordinary portal export cannot bypass the bound-proof denial.');}finally{$wpdb->update($wpdb->options,['option_value'=>$original],['option_name'=>$key],['%s'],['%s']);}}
   // Change only dependency content: approval labels cannot hide a stale package binding.
   $noteRow=$wpdb->get_row($wpdb->prepare('SELECT notes FROM '.Tables::product_versions().' WHERE id=%d',$f['product_version_id']),ARRAY_A);$notes=$noteRow['notes'];try{$wpdb->update(Tables::product_versions(),['notes'=>'changed after held-package decision'],['id'=>$f['product_version_id']],['%s'],['%d']);self::assertWPError($panel->process($post));}finally{$wpdb->update(Tables::product_versions(),['notes'=>$notes],['id'=>$f['product_version_id']],['%s'],['%d']);self::assertSame($noteRow,$wpdb->get_row($wpdb->prepare('SELECT notes FROM '.Tables::product_versions().' WHERE id=%d',$f['product_version_id']),ARRAY_A));}
   $u=wp_get_current_user();$u->add_cap('manage_digiforge_products',false);try{self::assertWPError($panel->process($post));}finally{$u->add_cap('manage_digiforge_products',true);}
   $bundle=PrintifyApiApprovalFixture::checked($panel->process(array_replace($post,['operation'=>'package_bundle'])));$file=tempnam(sys_get_temp_dir(),'shop2-bound-');file_put_contents($file,$bundle['package_bundle']);$zip=new ZipArchive();try{self::assertTrue($zip->open($file,ZipArchive::CHECKCONS));self::assertSame($raw,$zip->getFromName('held-package.json'));self::assertSame($f['proof']['record']['data']['result']['proof_sha256'],hash('sha256',$zip->getFromName('proof/local-sample.svg')));}finally{$zip->close();unlink($file);}
   // A different genuinely reviewed server selection cannot inherit this package's seal/decision.
   PrintifyApiApprovalFixture::checked($proofs->decide('personalized_pod',$next['hash'],'APPROVE','SYNTHETIC revised local proof only'));
   $selected=PrintifyApiApprovalFixture::checked((new DigiForge\Research\ArtworkPersonalizationIntake())->selectReviewed('personalized_pod',$f['context']['supplier_workflow_hash'],$f['context']['factory_hash'],$next['hash']));self::assertNotSame($f['intake']['intake_hash'],$selected['intake_hash']);self::assertWPError($panel->process($post));
   $newPost=array_replace($post,['personalization_hash'=>$next['hash']]);$prepared=PrintifyApiApprovalFixture::checked($panel->process(array_replace($newPost,['operation'=>'package_prepare','evidence_mode'=>'import','evidence_json'=>wp_json_encode($v['record']['evidence']),'parent_hash'=>$f['package']])));self::assertNotSame($f['package'],$prepared['package_hash']);$newPost['package_hash']=$prepared['package_hash'];$pending=PrintifyApiApprovalFixture::checked((new DigiForge\POD\ProductPackageRepository())->read('personalized_pod',$prepared['package_hash']));self::assertNull($pending['decision']);self::assertWPError($panel->process($newPost));
   PrintifyApiApprovalFixture::checked($panel->process(array_replace($newPost,['operation'=>'package_decide','decision'=>'APPROVE','note'=>'SYNTHETIC new exact-bound held review'])));$post=$newPost;$f['package']=$prepared['package_hash'];
   $baseline=PrintifyApiApprovalFixture::checked($panel->process($post));self::assertIsString($baseline['package_export'],'Fresh new package must be valid before race injection.');
   // Genuine source-session revocation during the final export must prevent bytes returning.
   $reads=0;$trip=static function(string $q)use(&$reads,$f):string{if(str_contains($q,'digiforge_product_package_'.$f['package'].'_decision')&&++$reads===6)WP_Session_Tokens::get_instance(1)->destroy(wp_get_session_token());return $q;};add_filter('query',$trip);try{self::assertWPError($panel->process($post));self::assertGreaterThanOrEqual(6,$reads);}finally{remove_filter('query',$trip);}
   self::assertSame(0,$http);self::assertTrue(DigiForge\Core\Settings::get('stop_all'));self::assertTrue(DigiForge\Core\Settings::safety_locked());self::assertFalse(DigiForge\Core\Settings::get('automation_armed',false));
  }finally{remove_filter('pre_http_request',$deny,PHP_INT_MAX);}
 }
